#include "semantic.h"
#include "symbol_table.h"
#include <stdio.h>
static SymbolTable table; static int errors;
static Type check_expr(Expr*e){if(!e)return TYPE_ERROR;Type a,b;Symbol*s;switch(e->kind){case EX_INT:return e->inferred=TYPE_INT;case EX_FLOAT:return e->inferred=TYPE_FLOAT;case EX_BOOL:return e->inferred=TYPE_BOOL;case EX_NAME:s=symbols_lookup(&table,e->as.name);if(!s){fprintf(stderr,"line %d: semantic error: '%s' used before declaration or outside its scope\n",e->line,e->as.name);errors++;return e->inferred=TYPE_ERROR;}return e->inferred=s->type;case EX_UNARY:a=check_expr(e->as.unary.child);if(e->as.unary.op==OP_NOT){if(a!=TYPE_BOOL&&a!=TYPE_ERROR){fprintf(stderr,"line %d: '!' requires bool\n",e->line);errors++;}return e->inferred=TYPE_BOOL;}if(a!=TYPE_INT&&a!=TYPE_FLOAT&&a!=TYPE_ERROR){fprintf(stderr,"line %d: unary '-' requires a number\n",e->line);errors++;}return e->inferred=a;case EX_BINARY:a=check_expr(e->as.binary.left);b=check_expr(e->as.binary.right);if(a==TYPE_ERROR||b==TYPE_ERROR)return e->inferred=TYPE_ERROR;switch(e->as.binary.op){case OP_ADD:case OP_SUB:case OP_MUL:case OP_DIV:if((a!=TYPE_INT&&a!=TYPE_FLOAT)||(b!=TYPE_INT&&b!=TYPE_FLOAT)){fprintf(stderr,"line %d: arithmetic operators require numeric operands\n",e->line);errors++;return e->inferred=TYPE_ERROR;}if(a!=b){fprintf(stderr,"line %d: mixed numeric types are not supported; use matching types\n",e->line);errors++;return e->inferred=TYPE_ERROR;}return e->inferred=a;case OP_MOD:if(a!=TYPE_INT||b!=TYPE_INT){fprintf(stderr,"line %d: modulo requires int operands\n",e->line);errors++;return e->inferred=TYPE_ERROR;}return e->inferred=TYPE_INT;case OP_LT:case OP_LE:case OP_GT:case OP_GE:if(a!=b||a==TYPE_BOOL){fprintf(stderr,"line %d: ordered comparison requires matching numeric operands\n",e->line);errors++;}return e->inferred=TYPE_BOOL;case OP_EQ:case OP_NE:if(a!=b){fprintf(stderr,"line %d: equality operands must have matching types\n",e->line);errors++;}return e->inferred=TYPE_BOOL;case OP_AND:case OP_OR:if(a!=TYPE_BOOL||b!=TYPE_BOOL){fprintf(stderr,"line %d: logical operators require bool operands\n",e->line);errors++;}return e->inferred=TYPE_BOOL;default:return e->inferred=TYPE_ERROR;}}return TYPE_ERROR;}
static void check_stmt(Stmt*s){if(!s)return;switch(s->kind){case ST_BLOCK:symbols_enter(&table);for(size_t i=0;s->as.block&&i<s->as.block->count;i++)check_stmt(s->as.block->items[i]);symbols_leave(&table);break;case ST_DECL:if(!symbols_insert(&table,s->as.decl.name,s->as.decl.type)){fprintf(stderr,"line %d: semantic error: '%s' is already declared in this scope\n",s->line,s->as.decl.name);errors++;}if(s->as.decl.init){Type v=check_expr(s->as.decl.init);if(v!=TYPE_ERROR&&v!=s->as.decl.type){fprintf(stderr,"line %d: cannot initialize %s with %s\n",s->line,type_name(s->as.decl.type),type_name(v));errors++;}}break;case ST_ASSIGN:{Symbol*x=symbols_lookup(&table,s->as.assign.name);Type v=check_expr(s->as.assign.value);if(!x){fprintf(stderr,"line %d: semantic error: '%s' used before declaration or outside its scope\n",s->line,s->as.assign.name);errors++;}else if(v!=TYPE_ERROR&&x->type!=v){fprintf(stderr,"line %d: cannot assign %s to %s variable '%s'\n",s->line,type_name(v),type_name(x->type),x->name);errors++;}break;}case ST_PRINT:check_expr(s->as.print);break;case ST_EXPR:check_expr(s->as.expression);break;case ST_IF:{Type c=check_expr(s->as.branch.condition);if(c!=TYPE_BOOL&&c!=TYPE_ERROR){fprintf(stderr,"line %d: if condition must be bool\n",s->line);errors++;}check_stmt(s->as.branch.yes);check_stmt(s->as.branch.no);break;}case ST_WHILE:{Type c=check_expr(s->as.loop.condition);if(c!=TYPE_BOOL&&c!=TYPE_ERROR){fprintf(stderr,"line %d: while condition must be bool\n",s->line);errors++;}check_stmt(s->as.loop.body);break;}case ST_ERROR:break;}}
int semantic_check(StmtList*p){symbols_init(&table);errors=0;for(size_t i=0;p&&i<p->count;i++)check_stmt(p->items[i]);return errors;}

